<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
require_once __DIR__.'/passenger_auth_helpers.php';
require_once __DIR__.'/saas_feature_helpers.php';
$db=saas_db();$slug=trim((string)($_GET['slug']??''));$token=trim((string)($_GET['token']??''));$tourId=(int)($_GET['tour_id']??0);$accountMode=isset($_GET['account']);$booking=null;
if($accountMode&&passenger_authenticated()){$booking=passenger_booking($tourId);}
elseif($slug!==''&&preg_match('/^[a-f0-9]{64}$/',$token)){$q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.id passenger_profile_id,pp.full_name,pp.phone,pp.email,t.id tour_id,t.organization_id,t.name tour_name,t.slug,o.currency,o.name organization_name FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND o.status='ACTIVE' LIMIT 1");$q->execute([$slug,hash('sha256',$token)]);$booking=$q->fetch();if(!$booking||$booking['status']!=='ACTIVE'){http_response_code(404);exit('Active booking not found.');}}
else{http_response_code(404);exit('Booking link is invalid.');}
$features=saas_enabled_features((int)$booking['tour_id']);$selected=[];$q=$db->prepare("SELECT tpf.*,tfo.option_label,tfo.option_value,tfo.price FROM tour_passenger_features tpf LEFT JOIN tour_feature_options tfo ON tfo.id=tpf.option_id WHERE tpf.tour_passenger_id=? AND tpf.tour_id=? AND tpf.status='SELECTED'");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);foreach($q->fetchAll() as $r)$selected[(int)$r['tour_feature_id']]=$r;
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$newTotal=0;$payload=[];foreach($features as $f){$fid=(int)$f['id'];$kind=(string)$f['kind'];$value=trim((string)($_POST['feature_'.$fid]??''));$optionId=null;$valueText=null;$unit=0.0;if($kind==='select'){if($value==='')continue;$q=$db->prepare("SELECT id,option_value,price FROM tour_feature_options WHERE id=? AND tour_feature_id=? AND status='ACTIVE' LIMIT 1");$q->execute([(int)$value,$fid]);$opt=$q->fetch();if(!$opt)throw new RuntimeException('Invalid feature option selected.');$optionId=(int)$opt['id'];$unit=(float)$opt['price'];$valueText=(string)($opt['option_value']??'');}else{if($value==='')continue;if(strlen($value)>500)throw new RuntimeException('Feature value is too long.');$valueText=$value;}
$payload[]=['fid'=>$fid,'option_id'=>$optionId,'value_text'=>$valueText,'unit'=>$unit];$newTotal+=round($unit,2);}
$db->beginTransaction();$q=$db->prepare("SELECT tp.id,tp.fee,tp.discount FROM tour_passengers tp JOIN tours t ON t.id=tp.tour_id WHERE tp.id=? AND tp.tour_id=? AND t.organization_id=? AND tp.status='ACTIVE' FOR UPDATE");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id'],(int)$booking['organization_id']]);$locked=$q->fetch();if(!$locked)throw new RuntimeException('Booking is no longer active.');$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=? AND tour_passenger_id=?');$q->execute([(int)$booking['tour_id'],(int)$booking['tp_id']]);$paid=(float)$q->fetchColumn();$baseTotal=max(0,(float)$locked['fee']-(float)$locked['discount']);$newGross=round($baseTotal+$newTotal,2);if($paid>$newGross+0.005)throw new RuntimeException('These changes would make the paid amount exceed the new booking total. Please contact the organizer.');
$q=$db->prepare("UPDATE tour_passenger_features SET status='CANCELLED' WHERE tour_passenger_id=? AND tour_id=? AND status='SELECTED'");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);$ins=$db->prepare('INSERT INTO tour_passenger_features(tour_id,tour_passenger_id,tour_feature_id,option_id,value_text,quantity,unit_price,total_price,status) VALUES(?,?,?,?,?,1,?,?,\'SELECTED\') ON DUPLICATE KEY UPDATE option_id=VALUES(option_id),value_text=VALUES(value_text),quantity=VALUES(quantity),unit_price=VALUES(unit_price),total_price=VALUES(total_price),status=\'SELECTED\'');foreach($payload as $p)$ins->execute([(int)$booking['tour_id'],(int)$booking['tp_id'],$p['fid'],$p['option_id'],$p['value_text'],$p['unit'],$p['unit']]);$db->commit();saas_audit('public.features_updated','tour_passenger',(int)$booking['tp_id'],json_encode(['feature_total'=>$newTotal,'gross_total'=>$newGross],JSON_UNESCAPED_UNICODE));$ok='Your tour options have been saved.';
$q=$db->prepare("SELECT tpf.*,tfo.option_label,tfo.option_value,tfo.price FROM tour_passenger_features tpf LEFT JOIN tour_feature_options tfo ON tfo.id=tpf.option_id WHERE tpf.tour_passenger_id=? AND tpf.tour_id=? AND tpf.status='SELECTED'");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);$selected=[];foreach($q->fetchAll() as $r)$selected[(int)$r['tour_feature_id']]=$r;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$featureTotal=0;foreach($selected as $s)$featureTotal+=(float)$s['total_price'];$baseTotal=max(0,(float)$booking['fee']-(float)$booking['discount']);$gross=$baseTotal+$featureTotal;$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=? AND tour_passenger_id=?');$q->execute([(int)$booking['tour_id'],(int)$booking['tp_id']]);$paid=(float)$q->fetchColumn();$due=max(0,$gross-$paid);$currency=$booking['currency']?:'BDT';$back=$accountMode?'public_booking.php?tour_id='.(int)$booking['tour_id'].'&account=1':'public_booking.php?slug='.rawurlencode($slug).'&token='.rawurlencode($token);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tour Options — <?=saas_h($booking['tour_name'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Arial,sans-serif}.wrap{max-width:850px;margin:25px auto;padding:0 16px}.card{background:#fff;border-radius:18px;padding:22px;margin-bottom:18px;box-shadow:0 8px 30px #0000000b}.feature{border:1px solid #eaecf0;border-radius:14px;padding:16px;margin:12px 0}.feature h3{margin:0 0 5px}.muted{font-size:13px;color:#667085}.option{display:flex;gap:10px;align-items:center;padding:9px 0}.option input{width:auto}.text{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{padding:14px;background:#f8fafc;border-radius:12px}.stat b{display:block;font-size:20px;margin-top:4px}.btn{display:block;width:100%;padding:13px;border:0;border-radius:10px;background:#155eef;color:#fff;font-weight:800;font-size:15px}.ok{background:#ecfdf3;color:#067647;padding:12px;border-radius:10px}.err{background:#fef3f2;color:#b42318;padding:12px;border-radius:10px}@media(max-width:600px){.summary{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="<?=saas_h($back)?>">← My booking</a></p><section class="card"><h1>Tour Options</h1><p>Choose the optional services or preferences available for <strong><?=saas_h($booking['tour_name'])?></strong>.</p><?php if($ok):?><div class="ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="err"><?=saas_h($error)?></div><?php endif;?></section><?php if(!$features):?><section class="card"><p class="muted">No optional features are enabled for this tour.</p></section><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><?php foreach($features as $f):$fid=(int)$f['id'];$kind=(string)$f['kind'];$s=$selected[$fid]??null;?><section class="feature"><h3><?=saas_h($f['label'])?></h3><p class="muted"><?=saas_h($f['description'])?></p><?php if($kind==='select'):$opts=saas_feature_options($fid);if(!$opts):?><p class="muted">No options have been configured yet.</p><?php else:foreach($opts as $o):?><label class="option"><input type="radio" name="feature_<?=$fid?>" value="<?=saas_h((string)$o['id'])?>" <?=($s&&((int)$s['option_id']===(int)$o['id']))?'checked':''?>> <span><?=saas_h($o['option_label'])?><?php if((float)$o['price']!=0):?> — <?=number_format((float)$o['price'],2)?> <?=saas_h($currency)?><?php endif;?></span></label><?php endforeach;endif;else:?><input class="text" name="feature_<?=$fid?>" maxlength="500" value="<?=saas_h($s['value_text']??'')?>" placeholder="Enter details"><?php endif;?></section><?php endforeach;?><button class="btn" type="submit">Save tour options</button></form><?php endif;?><section class="card"><h2>Updated total</h2><div class="summary"><div class="stat">Base total<b><?=number_format($baseTotal,2)?> <?=saas_h($currency)?></b></div><div class="stat">Options<b><?=number_format($featureTotal,2)?> <?=saas_h($currency)?></b></div><div class="stat">Due<b><?=number_format($due,2)?> <?=saas_h($currency)?></b></div></div><p class="muted">Paid: <?=number_format($paid,2)?> <?=saas_h($currency)?> · Changes are priced from the server-side feature configuration.</p></section></main></body></html>